/// <summary>
/// Initializes a <c>PurchPurchaseOrderHeader</c> table record with the values from a <c>VendTable</c> table record.
/// </summary>
/// <param name="_vendTable">
/// The <c>VendTable</c> table record.
/// </param>
public void initFromVendTable(VendTable _vendTable)
{
    next initFromVendTable(_vendTable);

    this.AVAVendName = _vendTable.avaName();
}

public void initFromVendPurchOrderJour(VendPurchOrderJour _vendPurchOrderJour)
{
    VendFormLetterDocument avaVendFormletterDocument;

    next initFromVendPurchOrderJour(_vendPurchOrderJour);

    this.AVAPurchConfirmationDueDate    = _vendPurchOrderJour.AVAPurchConfirmationDueDate;

    this.avaGetHeaderFooterNotes(_vendPurchOrderJour, avaVendFormletterDocument);
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_common">Common</param>
/// <param name = "_vendFormLetterDocument">VendFormletterDocument</param>
/// <returns>SalesQuotationHeaderTmp</returns>
public void avaGetHeaderFooterNotes(Common _common, VendFormLetterDocument _vendFormLetterDocument)
{
    DocuRefSearch avaHeaderRefSearch, avaFooterRefSearch;

    avaHeaderRefSearch = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(_common,
                                                                _vendFormLetterDocument.DocuTypePurchOrder,
                                                                DocuRestriction::External,
                                                                AVATCVNotePosition::Top);

    avaFooterRefSearch = DocuRefSearch::avaNewTypeAndRestrictAndNotePositionSortDesc(_common,
                                                                _vendFormLetterDocument.DocuTypePurchOrder,
                                                                DocuRestriction::External,
                                                                AVATCVNotePosition::Bottom);

    [this.AVAHeaderNotes1,
        this.AVAHeaderNotes2,
        this.AVAHeaderNotes3,
        this.AVAHeaderNotes4,
        this.AVAHeaderNotes5] = this.avaDocuRefNotes(avaHeaderRefSearch);

    [this.AVAFooterNotes1,
        this.AVAFooterNotes2,
        this.AVAFooterNotes3,
        this.AVAFooterNotes4,
        this.AVAFooterNotes5] = this.avaDocuRefNotes(avaFooterRefSearch);

}

/// <summary>
/// Extension of initFromPurchTableAllVersions
/// </summary>
/// <param name = "_purchTableAllVersions">PurchTableAllVersions</param>
/// <param name = "_isPurchConfirmationRequest">boolean</param>
public void initFromPurchTableAllVersions(PurchTableAllVersions _purchTableAllVersions, boolean _isPurchConfirmationRequest)
{
    next initFromPurchTableAllVersions(_purchTableAllVersions, _isPurchConfirmationRequest);


    this.avaInitFromFormLetterRemarks2(FormLetterRemarks::find(_purchTableAllVersions.LanguageId, (_isPurchConfirmationRequest ? FormTextType::AVAPurchaseOrderConfirmationRequest2 : FormTextType::AVAPurchPurchaseOrder2)));
}

/// <summary>
/// Initializes a <c>PurchPurchaseOrderHeader</c> table record with the values from a <c>FormLetterRemarks</c> table record.
/// </summary>
/// <param name="_formLetterRemarks">
/// The <c>FormLetterRemarks</c> table record.
/// </param>
public void avaInitFromFormLetterRemarks(FormLetterRemarks _formLetterRemarks)
{
    this.AVAFormLetterRemarksTxt       = _formLetterRemarks.Txt;
}

/// <summary>
/// Initializes a <c>PurchPurchaseOrderHeader</c> table record with the values from a <c>FormLetterRemarks</c> table record.
/// </summary>
/// <param name="_formLetterRemarks">
/// The <c>FormLetterRemarks</c> table record.
/// </param>
public void avaInitFromFormLetterRemarks2(FormLetterRemarks _formLetterRemarks)
{
    this.AVAFormLetterRemarksTxt2   = _formLetterRemarks.Txt;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_search">DocuRefSearch</param>
/// <returns>container</returns>
public container avaDocuRefNotes(DocuRefSearch _search)
{
    DocuRef     docuRef;
    //Notes       result;
    int         counter = 0;
    container   retCon;
    #xppTexts

    if (_search)
    {
        docuRef.recordLevelSecurity(true);
        while (_search.next())
        {
            if(counter == 5)
            {
                throw error("@NDX:NoteAttachmentError");
            }

            retCon += _search.docuRef().Notes;
            counter++;
        }
    }

    return retCon;
}
